await page.goto('/ops/radar');

// The radar clock time rule: the clock time must be shown on the radar.
const clockTime = page.getByRole('timer');
await expect(clockTime).toBeVisible();
await expect(clockTime).toHaveText(/\d{1,2}:\d{2}/);

// The clock label rule: the clock must carry its label.
const clockLabel = page.getByRole('region', { name: /clock/i });
await expect(clockLabel).toBeVisible();
await expect(clockLabel).toContainText(/clock|time/i);
